<?php
 namespace Pterodactyl\Http\Middleware; use GuzzleHttp\Client; use Illuminate\Http\Request; use Illuminate\Http\Response; use Pterodactyl\Events\Auth\FailedCaptcha; use Illuminate\Contracts\Config\Repository; use Illuminate\Contracts\Events\Dispatcher; use Symfony\Component\HttpKernel\Exception\HttpException; class VerifyReCaptcha { public function __construct(private Dispatcher $dispatcher, private Repository $config) { } public function handle(Request $request, \Closure $next): mixed { if (!$this->config->get('recaptcha.enabled')) { return $next($request); } $turnstile = $this->isTurnstile(); $response = $this->getResponseToken($request, $turnstile); if (!empty($response)) { $client = new Client(); $res = $client->post($this->config->get($turnstile ? 'recaptcha.turnstile_domain' : 'recaptcha.domain'), [ 'form_params' => [ 'secret' => $this->config->get($turnstile ? 'recaptcha.turnstile_secret_key' : 'recaptcha.secret_key'), 'response' => $response, ], ]); if ($res->getStatusCode() === 200) { $result = json_decode($res->getBody()); if ($result->success && (!$this->config->get('recaptcha.verify_domain') || $this->isResponseVerified($result, $request))) { return $next($request); } } } $this->dispatcher->dispatch( new FailedCaptcha( $request->ip(), !empty($result) ? ($result->hostname ?? null) : null ) ); throw new HttpException(Response::HTTP_BAD_REQUEST, sprintf('Failed to validate %s data.', $turnstile ? 'Turnstile' : 'reCAPTCHA')); } private function isTurnstile(): bool { return $this->config->get('recaptcha.provider') === 'turnstile'; } private function getResponseToken(Request $request, bool $turnstile): ?string { if ($turnstile && $request->filled('cf-turnstile-response')) { return $request->input('cf-turnstile-response'); } return $request->filled('g-recaptcha-response') ? $request->input('g-recaptcha-response') : null; } private function isResponseVerified(\stdClass $result, Request $request): bool { if (!$this->config->get('recaptcha.verify_domain')) { return false; } $url = parse_url($request->url()); return $result->hostname === array_get($url, 'host'); } } 